def node_readiness_report(
    units: list[dict[str, Any]],
    coverage: dict[str, Any],
    deps: dict[str, Any],
) -> dict[str, Any]:
    coverage_blocked = bool(coverage.get("blockers"))
    runtime_status = runtime_enablement_status(units)
    compiler_contract_incomplete = runtime_status.get("compiler_contract_complete") is False
    runtime_certification_incomplete = runtime_status.get("executable_lifecycle_certification_complete") is False
    if coverage_blocked:
        status = "blocked_plans_incomplete"
    elif compiler_contract_incomplete:
        status = "blocked_compiler_contract_incomplete"
    elif runtime_certification_incomplete:
        status = "blocked_runtime_certification_incomplete"
    else:
        status = "ready_for_node_compile"
    if coverage_blocked:
        status_reason = "PlanUnit coverage or required metadata is incomplete; see missing_required_metadata and coverage_report blockers."
    elif compiler_contract_incomplete:
        status_reason = "Plans are indexed with required PlanUnit metadata, but the PlanCompile compiler contract remains incomplete and runtime node artifact generation remains disabled."
    elif runtime_certification_incomplete:
        status_reason = "Plans are indexed with required PlanUnit metadata and the PlanCompile compiler contract is accepted, but native runtime readiness remains blocked by PNC-019 until an executable lifecycle certification harness passes and records evidence for the enabled runtime boundary."
    else:
        status_reason = "Plans are indexed with required PlanUnit metadata and an accepted PlanCompile compiler contract; the PlanUnit index remains non-emitting and native runtime implementation must materialize artifacts only through the compiler, Executor intake, activation, and Goal Runtime certification contracts."
    build_order_blockers = []
    if deps.get("unresolved_references"):
        build_order_blockers.append({"blocker_type": "unresolved_dependency_references", "items": deps["unresolved_references"]})
    if deps.get("cycle_blockers"):
        build_order_blockers.append({"blocker_type": "dependency_cycles", "items": deps["cycle_blockers"]})
    if deps.get("downstream_blocked_nodes"):
        build_order_blockers.append({"blocker_type": "dependency_cycle_downstream_blocked_nodes", "items": deps["downstream_blocked_nodes"]})

    gui_units = [
        {
            "plan_unit_id": unit_id(unit),
            "owner_doc": unit.get("owner_doc"),
            "source_location": unit.get("source_location"),
        }
        for unit in units
        if unit.get("gui_related") is True
    ]
    source_preserving_units = [
        {
            "plan_unit_id": unit_id(unit),
            "owner_doc": unit.get("owner_doc"),
            "split_recommended": unit.get("split_recommended", False),
            "source_location": unit.get("source_location"),
        }
        for unit in units
        if isinstance(unit.get("node_compile_hint"), dict)
        and unit["node_compile_hint"].get("mode") == "source_preserving_planunit"
    ]
    next_required_action = (
        "Materialize and run the PNC-019 executable lifecycle certification harness for Approve And Build through PlanCompile, Executor intake, activation, Orchestrator projection, testing evidence, restart/cancellation, and negative-case rejection before any PlanCompile runtime artifacts, NodeSeeds, WorkNodes, executable tasks, or final node queues are materialized."
        if runtime_certification_incomplete
        else "PNC-019 executable lifecycle certification is current; ordinary PlanCompile output may start only through the certified runtime compiler, Executor intake, activation, and Goal Runtime certification contracts, while this index still emits no NodeSeeds, WorkNodes, queues, runtime launches, final manifests, implementation files, or production build tasks."
    )

    return {
        "schema_id": "pm.plan_index.node_readiness_report.v1",
        "generated_at_utc": utc_now(),
        "status": status,
        "status_reason": status_reason,
        "source_plan_unit_index": "Plans/.plan_index/plan_units.jsonl",
        "plan_unit_count": len(units),
        "missing_required_metadata": coverage.get("issues", {}).get("missing_required_metadata", []),
        "dependency_graph_summary": deps.get("summary", {}),
        "build_order_blockers": build_order_blockers,
        "risk_and_reasoning_summary": {
            "risk_class_counts": counter_dict([unit.get("risk_class") for unit in units]),
            "reasoning_tier_counts": counter_dict([unit.get("reasoning_tier") for unit in units]),
            "status_counts": counter_dict([unit.get("status") for unit in units]),
            "unit_type_counts": counter_dict([unit.get("unit_type") for unit in units]),
            "source_preserving_unit_count": len(source_preserving_units),
            "source_preserving_units": source_preserving_units,
        },
        "gui_related_units": {
            "count": len(gui_units),
            "units": gui_units,
        },
        "runtime_enablement_status": runtime_status,
        "no_worknodes_created": True,
        "no_executable_build_tasks_created": True,
        "no_final_node_queues_created": True,
        "nodeseed_candidates_created": False,
        "next_required_action": next_required_action,
    }

def require_live_current_evidence(path: Path) -> str:
    """Refuse to mutate immutable historical evidence bundles."""
    try:
        path_ref = path.resolve().relative_to(ROOT.resolve()).as_posix()
    except (OSError, ValueError):
        raise SystemExit(f"evidence path must resolve inside the repository: {path}") from None
    try:
        manifest = load_json(EVIDENCE_ARTIFACT_BINDING_MANIFEST)
    except Exception as exc:  # noqa: BLE001
        raise SystemExit(f"evidence binding manifest is unavailable: {exc}") from None
    matches = [
        entry
        for entry in manifest.get("entries", [])
        if isinstance(entry, dict) and entry.get("path") == path_ref
    ]
    if len(matches) != 1:
        raise SystemExit(f"evidence path must have exactly one binding-mode entry: {path_ref}")
    mode = matches[0].get("mode")
    if mode != "live_current":
        raise SystemExit(
            f"refusing to refresh immutable {mode!r} evidence bundle: {path_ref}; "
            "create or update a declared live_current successor instead"
        )
    return path_ref

def sync_plan_sharding_evidence(evidence_path: Path, report_path: Path) -> dict[str, Any]:
    require_live_current_evidence(evidence_path)
    data = load_json(evidence_path)
    report = load_json(report_path)
    existing_by_path = {
        artifact.get("path"): artifact
        for artifact in data.get("artifacts", [])
        if artifact.get("path")
    }

    def artifact_for(path: str, *, note: str | None = None) -> dict[str, Any]:
        target = repo_path(path)
        artifact = {k: v for k, v in existing_by_path.get(path, {}).items() if k not in {"sha256", "path"}}
        artifact["path"] = path
        if note is not None:
            artifact["note"] = note
        if target.exists() and target.is_file():
            artifact["sha256"] = sha256_file(target)
        return artifact

    artifacts: list[dict[str, Any]] = [
        artifact_for(str(report.get("config_path", "Plans/sharding_config.json"))),
        artifact_for(str(report_path.relative_to(ROOT))),
    ]
    check_report_path = report_path.with_name("shard-check-report.json")
    if not check_report_path.exists() or not check_report_path.is_file():
        raise SystemExit(
            "live-current plan-sharding evidence requires the adjacent shard-check-report.json: "
            f"{check_report_path.relative_to(ROOT)}"
        )
    artifacts.append(artifact_for(str(check_report_path.relative_to(ROOT))))
    for doc in report.get("docs", []):
        source_path = doc.get("source", {}).get("path")
        if source_path:
            artifacts.append(artifact_for(str(source_path), note="Configured shard source."))
        index_path = doc.get("index_path")
        if index_path:
            artifacts.append(artifact_for(str(index_path)))
        manifest_path = doc.get("manifest_path")
        if manifest_path:
            artifacts.append(artifact_for(str(manifest_path)))
        for shard in doc.get("shards", []):
            shard_path = shard.get("path")
            if shard_path:
                artifacts.append(artifact_for(str(shard_path)))

    old_paths = [artifact.get("path") for artifact in data.get("artifacts", [])]
    new_paths = [artifact.get("path") for artifact in artifacts]
    changed = old_paths != new_paths or data.get("artifacts") != artifacts
    if changed:
        data["artifacts"] = artifacts
        write_json(evidence_path, data)
    return {
        "path": str(evidence_path.relative_to(ROOT)),
        "changed": changed,
        "artifact_count": len(artifacts),
        "removed_paths": sorted(set(old_paths) - set(new_paths)),
        "added_paths": sorted(set(new_paths) - set(old_paths)),
    }

def validate_evidence_file(
    path: Path,
    schema: dict[str, Any],
    *,
    known_node_ids: set[str] | None = None,
    expected_node_id: str | None = None,
    artifact_binding_mode: str = "live_current",
    forbidden_live_current_tokens: list[str] | None = None,
) -> list[dict[str, Any]]:
    failures: list[dict[str, Any]] = []
    try:
        data = load_json(path)
    except Exception as exc:  # noqa: BLE001
        return [{"path": rel(path), "error": str(exc)}]
    for error in validate_schema(data, schema, schema):
        failures.append({"path": rel(path), "error": error})
    if artifact_binding_mode == "live_current":
        serialized = json.dumps(data, sort_keys=True, ensure_ascii=False).casefold()
        for token in forbidden_live_current_tokens or FORBIDDEN_LIVE_CURRENT_EVIDENCE_TOKENS:
            if token.casefold() in serialized:
                failures.append({
                    "path": rel(path),
                    "error": "forbidden_live_current_evidence_claim",
                    "token": token,
                })
    actual_node_id = data.get("node", {}).get("node_id")
    if expected_node_id is not None and actual_node_id != expected_node_id:
        failures.append(
            {
                "path": rel(path),
                "error": "evidence_node_id_mismatch",
                "expected_node_id": expected_node_id,
                "actual_node_id": actual_node_id,
            }
        )
    if known_node_ids is not None and actual_node_id not in known_node_ids:
        failures.append(
            {
                "path": rel(path),
                "node_id": actual_node_id,
                "error": "evidence_node_id_not_in_plan_graph",
                "plan_graph": "Plans/plan_graph.json",
            }
        )
    for artifact in data.get("artifacts", []):
        artifact_ref = artifact.get("path")
        expected_hash = artifact.get("sha256")
        if not artifact_ref or not expected_hash:
            continue
        if artifact_binding_mode == "historical_snapshot":
            if not re.fullmatch(r"[0-9a-f]{64}", str(expected_hash)):
                failures.append({
                    "path": rel(path),
                    "artifact": artifact_ref,
                    "error": "historical_artifact_hash_not_sha256",
                })
            continue
        artifact_path, path_error = exact_path(artifact_ref)
        if path_error:
            failures.append({"path": rel(path), "artifact": artifact_ref, **ref_failure(path_error, "artifact_ref")})
            continue
        assert artifact_path is not None
        if not artifact_path.exists():
            failures.append({"path": rel(path), "artifact": artifact_ref, "error": "missing_artifact"})
            continue
        actual_hash = sha256_file(artifact_path)
        if actual_hash != expected_hash:
            failures.append(
                {
                    "path": rel(path),
                    "artifact": artifact_ref,
                    "error": "artifact_hash_stale",
                    "expected": expected_hash,
                    "actual": actual_hash,
                }
            )
    return failures

def load_evidence_artifact_binding_modes() -> tuple[dict[str, dict[str, Any]], list[dict[str, Any]], dict[str, int]]:
    """Load the fail-closed historical-snapshot versus live-current evidence map."""
    failures: list[dict[str, Any]] = []
    try:
        schema = load_json(EVIDENCE_ARTIFACT_BINDING_MANIFEST_SCHEMA)
        manifest = load_json(EVIDENCE_ARTIFACT_BINDING_MANIFEST)
    except Exception as exc:  # noqa: BLE001
        return {}, [{"path": rel(EVIDENCE_ARTIFACT_BINDING_MANIFEST), "error": "evidence_binding_manifest_unavailable", "detail": str(exc)}], {}

    for error in validate_schema(manifest, schema, schema):
        failures.append({"path": rel(EVIDENCE_ARTIFACT_BINDING_MANIFEST), "error": "evidence_binding_manifest_schema_invalid", "detail": error})
    forbidden_live_current_tokens = [
        str(token)
        for token in manifest.get("forbidden_live_current_tokens", [])
        if isinstance(token, str) and token
    ]
    if tuple(forbidden_live_current_tokens) != FORBIDDEN_LIVE_CURRENT_EVIDENCE_TOKENS:
        failures.append({
            "path": rel(EVIDENCE_ARTIFACT_BINDING_MANIFEST),
            "error": "forbidden_live_current_tokens_mismatch",
            "expected": list(FORBIDDEN_LIVE_CURRENT_EVIDENCE_TOKENS),
            "actual": forbidden_live_current_tokens,
        })
    entries: dict[str, dict[str, Any]] = {}
    census = Counter()
    for index, entry in enumerate(manifest.get("entries", [])):
        path_ref = str(entry.get("path", ""))
        mode = str(entry.get("mode", ""))
        label = f"{rel(EVIDENCE_ARTIFACT_BINDING_MANIFEST)}#/entries/{index}"
        if path_ref in entries:
            failures.append({"path": label, "error": "duplicate_evidence_binding_path", "evidence": path_ref})
            continue
        resolved, path_error = exact_path(path_ref)
        if path_error:
            failures.append({"path": label, "error": "evidence_binding_path_unresolved", "evidence": path_ref, "detail": path_error})
            continue
        if resolved is None or not resolved.is_file():
            failures.append({"path": label, "error": "evidence_binding_path_not_file", "evidence": path_ref})
            continue
        try:
            evidence_bundle = load_json(resolved)
        except Exception as exc:  # noqa: BLE001
            failures.append({"path": path_ref, "error": "evidence_binding_bundle_unreadable", "detail": str(exc)})
            continue
        expected_node_id = entry.get("node_id")
        actual_node_id = evidence_bundle.get("node", {}).get("node_id")
        if expected_node_id != actual_node_id:
            failures.append({
                "path": path_ref,
                "error": "evidence_binding_node_id_mismatch",
                "expected_node_id": expected_node_id,
                "actual_node_id": actual_node_id,
            })
        if mode == "historical_snapshot":
            expected_hash = entry.get("bundle_sha256")
            actual_hash = sha256_file(resolved)
            if expected_hash != actual_hash:
                failures.append({
                    "path": path_ref,
                    "error": "historical_evidence_bundle_hash_mismatch",
                    "expected": expected_hash,
                    "actual": actual_hash,
                })
        elif mode == "live_current" and "bundle_sha256" in entry:
            failures.append({"path": label, "error": "live_current_bundle_must_not_pin_its_own_mutable_hash"})
        entries[path_ref] = entry
        census[mode] += 1

    discovered = {rel(path) for path in evidence_paths([])}
    declared = set(entries)
    for path_ref in sorted(discovered - declared):
        failures.append({"path": path_ref, "error": "evidence_binding_mode_missing"})
    for path_ref in sorted(declared - discovered):
        failures.append({"path": path_ref, "error": "evidence_binding_mode_orphaned"})
    expected_census = {
        "historical_snapshot": manifest.get("expected_historical_snapshot_count"),
        "live_current": manifest.get("expected_live_current_count"),
    }
    actual_census = {key: census.get(key, 0) for key in expected_census}
    if actual_census != expected_census:
        failures.append({
            "path": rel(EVIDENCE_ARTIFACT_BINDING_MANIFEST),
            "error": "evidence_binding_mode_census_mismatch",
            "expected": expected_census,
            "actual": actual_census,
        })
    return entries, failures, actual_census

def cmd_verify_spec_lock(args: argparse.Namespace) -> dict[str, Any]:
    spec_path = PLANS / "Spec_Lock.json"
    failures: list[dict[str, Any]] = []
    try:
        spec = load_json(spec_path)
    except Exception as exc:  # noqa: BLE001
        return report_status("verify-spec-lock", [{"path": rel(spec_path), "error": str(exc)}])

    files = spec.get("canonical_ssot_hashes", {}).get("files", [])
    checked = []
    for entry in files:
        entry_ref = entry.get("path", "")
        entry_path, path_error = exact_path(entry_ref)
        expected = entry.get("sha256")
        if path_error:
            failures.append({**path_error, "error": path_error["error"].replace("_ref", "_locked_file")})
            continue
        assert entry_path is not None
        if not entry_path.exists():
            failures.append({"path": entry_ref, "error": "missing_locked_file"})
            continue
        actual = sha256_file(entry_path)
        checked.append({"path": entry_ref, "sha256": actual})
        if expected != actual:
            failures.append(
                {
                    "path": entry_ref,
                    "error": "stale_hash",
                    "expected": expected,
                    "actual": actual,
                }
            )

    return report_status(
        "verify-spec-lock",
        failures,
        locked_files_checked=len(checked),
        locked_files=checked,
    )

def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("ledger_dir", help="Plans/ledgers/v2/<ledger_id>")
    args = parser.parse_args()

    ledger_dir = Path(args.ledger_dir)
    if not ledger_dir.is_absolute():
        ledger_dir = ROOT / ledger_dir

    errors: list[str] = []
    warnings: list[str] = []
    required_paths = [
        ledger_dir / "manifest.json",
        ledger_dir / "events.jsonl",
        ledger_dir / "records/design_atoms.jsonl",
        ledger_dir / "records/decisions.jsonl",
        ledger_dir / "records/questions.jsonl",
        ledger_dir / "records/blockers.jsonl",
        ledger_dir / "records/corrections.jsonl",
        ledger_dir / "state/current.json",
        ledger_dir / "state/handoff.json",
        ledger_dir / "state/open_items.json",
        ledger_dir / "state/compile_queue.json",
        ledger_dir / "state/operating_capsule.json",
        ledger_dir / "validation/ledger_health.json",
    ]
    for path in required_paths:
        if not path.exists():
            errors.append(f"missing {rel(path)}")
    if errors:
        print(json.dumps({"status": "fail", "errors": errors}, indent=2))
        return 1

    manifest = load_json(ledger_dir / "manifest.json")
    lid = manifest.get("ledger_id")
    if not lid:
        errors.append("manifest missing ledger_id")

    events = load_jsonl(ledger_dir / "events.jsonl")
    atoms = load_jsonl(ledger_dir / "records/design_atoms.jsonl")
    decisions = load_jsonl(ledger_dir / "records/decisions.jsonl")
    questions = load_jsonl(ledger_dir / "records/questions.jsonl")
    blockers = load_jsonl(ledger_dir / "records/blockers.jsonl")
    corrections = load_jsonl(ledger_dir / "records/corrections.jsonl")
    current = load_json(ledger_dir / "state/current.json")
    handoff = load_json(ledger_dir / "state/handoff.json")
    open_items = load_json(ledger_dir / "state/open_items.json")
    compile_queue = load_json(ledger_dir / "state/compile_queue.json")
    operating_capsule = load_json(ledger_dir / "state/operating_capsule.json")
    health = load_json(ledger_dir / "validation/ledger_health.json")

    ids = {
        "event": validate_record_stream(str(lid), events, "event", "event_id", errors),
        "atom": validate_record_stream(str(lid), atoms, "atom", "atom_id", errors),
        "decision": validate_record_stream(str(lid), decisions, "decision", "decision_id", errors),
        "question": validate_record_stream(str(lid), questions, "question", "question_id", errors),
        "blocker": validate_record_stream(str(lid), blockers, "blocker", "blocker_id", errors),
        "correction": validate_record_stream(str(lid), corrections, "correction", "correction_id", errors),
    }

    for state_name, state in [
        ("current.json", current),
        ("handoff.json", handoff),
        ("open_items.json", open_items),
        ("compile_queue.json", compile_queue),
        ("operating_capsule.json", operating_capsule),
        ("ledger_health.json", health),
    ]:
        if state.get("ledger_id") != lid:
            errors.append(f"{state_name} ledger_id mismatch")

    record_counts = manifest.get("record_counts", {})
    expected_counts = {
        "events": len(events),
        "design_atoms": len(atoms),
        "decisions": len(decisions),
        "questions": len(questions),
        "blockers": len(blockers),
        "corrections": len(corrections),
    }
    for key, expected in expected_counts.items():
        if record_counts.get(key) != expected:
            errors.append(f"manifest record_counts.{key}={record_counts.get(key)!r} but actual is {expected}")

    atom_status_counts = count_by(atoms, "status")
    decision_status_counts = count_by(decisions, "status")
    question_status_counts = count_by(questions, "status")
    blocker_status_counts = count_by(blockers, "status")

    design_atom_schema = load_json(PLANS / "ledgers/v2/schemas/design_atom.schema.json")
    atom_required_fields = set(map(str, design_atom_schema.get("required", [])))
    allowed_atom_types = schema_enum(design_atom_schema, "atom_type")
    allowed_atom_statuses = schema_enum(design_atom_schema, "status")
    for atom in atoms:
        atom_id = atom.get("atom_id")
        missing_required = sorted(field for field in atom_required_fields if field not in atom)
        if missing_required:
            errors.append(f"atom {atom_id} missing required fields from design_atom.schema.json: {missing_required}")
        atom_type = atom.get("atom_type")
        if allowed_atom_types and atom_type not in allowed_atom_types:
            errors.append(f"atom {atom_id} atom_type {atom_type!r} is not allowed by design_atom.schema.json")
        atom_status = atom.get("status")
        if allowed_atom_statuses and atom_status not in allowed_atom_statuses:
            errors.append(f"atom {atom_id} status {atom_status!r} is not allowed by design_atom.schema.json")

    current_count_expectations = {
        "accepted_decisions_count": decision_status_counts.get("accepted", 0),
        "design_atoms_total": len(atoms),
        "ready_for_plan_compile_atoms": atom_status_counts.get("ready_for_plan_compile", 0),
        "candidate_atoms_count": atom_status_counts.get("candidate", 0),
        "open_questions_count": question_status_counts.get("open", 0),
        "deferred_questions_count": question_status_counts.get("deferred", 0),
        "open_blockers_count": blocker_status_counts.get("open", 0),
    }
    for key, expected in current_count_expectations.items():
        if current.get(key) != expected:
            errors.append(f"current.json {key}={current.get(key)!r} but actual is {expected}")

    health_summary = health.get("summary", {})
    health_count_expectations = {
        "events": len(events),
        "design_atoms": len(atoms),
        "decisions": len(decisions),
        "open_questions": question_status_counts.get("open", 0),
        "deferred_questions": question_status_counts.get("deferred", 0),
        "open_blockers": blocker_status_counts.get("open", 0),
        "compile_queue_items": len(compile_queue.get("items", [])),
    }
    for key, expected in health_count_expectations.items():
        if health_summary.get(key) != expected:
            errors.append(f"ledger_health summary.{key}={health_summary.get(key)!r} but actual is {expected}")

    if len(open_items.get("open_questions", [])) != current_count_expectations["open_questions_count"]:
        errors.append("open_items open_questions count disagrees with records/current")
    if len(open_items.get("deferred_questions", [])) != current_count_expectations["deferred_questions_count"]:
        errors.append("open_items deferred_questions count disagrees with records/current")
    if len(open_items.get("open_blockers", [])) != current_count_expectations["open_blockers_count"]:
        errors.append("open_items open_blockers count disagrees with records/current")

    current_phase = current.get("phase")
    queue_status = compile_queue.get("status")
    handoff_phase = handoff.get("current_phase")
    if current_phase != handoff_phase:
        errors.append(f"current phase {current_phase!r} disagrees with handoff phase {handoff_phase!r}")
    if current_phase != queue_status:
        errors.append(f"current phase {current_phase!r} disagrees with compile_queue status {queue_status!r}")

    compiled_phase = isinstance(current_phase, str) and current_phase.startswith("compiled")
    if compiled_phase:
        expected_manifest_status = "sealed" if current.get("governance_status") == "sealed" else "compiled"
        if manifest.get("status") != expected_manifest_status:
            errors.append(
                f"manifest status must be {expected_manifest_status} for compiled phase, "
                f"got {manifest.get('status')!r}"
            )
        if atom_status_counts.get("ready_for_plan_compile", 0):
            errors.append("compiled ledger still has ready_for_plan_compile design atoms")
        for item in compile_queue.get("items", []):
            if item.get("status") != "compiled":
                errors.append(f"compile_queue item {item.get('queue_id')} status is not compiled")
        if current.get("governance_status") == "sealed":
            if health.get("status") != "pass_governance_sealed":
                errors.append(f"ledger_health status must be pass_governance_sealed, got {health.get('status')!r}")
            if health_summary.get("governance_seal") != "passed":
                errors.append("ledger_health summary.governance_seal must be passed for sealed governance")
            if handoff.get("validation_state", {}).get("ledger_health") != health.get("status"):
                errors.append("handoff validation_state.ledger_health disagrees with ledger_health.status")
            if atom_status_counts.get("candidate", 0):
                errors.append("sealed ledger still has candidate design atoms")
            if atom_status_counts.get("ready_for_plan_compile", 0):
                errors.append("sealed ledger still has ready_for_plan_compile design atoms")
            for projection_name, projection in (("current", current), ("compile_queue", compile_queue)):
                if projection.get("candidate_compile_owner_docs"):
                    errors.append(
                        f"sealed ledger {projection_name} retains active candidate_compile_owner_docs; "
                        "move pre-seal candidates to source_lineage_pre_seal_candidate_compile_owner_docs"
                    )

    last_event_id = current.get("last_event_id")
    handoff_last_event_id = handoff.get("cursor", {}).get("last_event_id")
    queue_last_event_id = compile_queue.get("last_event_id")
    queue_terminal_event_id = compile_queue.get("terminal_ledger_event_id")
    cursor_last_event_id = current.get("cursor", {}).get("last_event_id")
    if last_event_id != handoff_last_event_id:
        errors.append("current last_event_id disagrees with handoff cursor.last_event_id")
    if last_event_id != queue_last_event_id:
        errors.append("current last_event_id disagrees with compile_queue last_event_id")
    if compiled_phase and queue_terminal_event_id != last_event_id:
        errors.append("compiled compile_queue terminal_ledger_event_id disagrees with current last_event_id")
    if cursor_last_event_id and cursor_last_event_id != last_event_id:
        errors.append("current cursor.last_event_id disagrees with current last_event_id")
    cursor_next_action = str(current.get("cursor", {}).get("next_action", ""))
    if current.get("governance_status") == "sealed" and "run final validators" in cursor_next_action.lower():
        errors.append("sealed ledger current cursor.next_action still asks to run final validators")
    if last_event_id and last_event_id not in ids["event"]:
        errors.append(f"last_event_id not found in events: {last_event_id}")
    if events and last_event_id != events[-1].get("event_id"):
        errors.append(f"last_event_id {last_event_id!r} is not the final event row {events[-1].get('event_id')!r}")

    current_audit_ref = current.get("latest_audit_ref")
    handoff_audit_ref = handoff.get("latest_audit_ref")
    queue_audit_ref = compile_queue.get("latest_audit_ref")
    current_audit_status = current.get("latest_audit_status")
    handoff_audit_status = handoff.get("latest_audit_status")
    queue_audit_status = compile_queue.get("latest_audit_status")
    if current_audit_ref != handoff_audit_ref:
        errors.append("current latest_audit_ref disagrees with handoff latest_audit_ref")
    if current_audit_ref != queue_audit_ref:
        errors.append("current latest_audit_ref disagrees with compile_queue latest_audit_ref")
    if current_audit_status != handoff_audit_status:
        errors.append("current latest_audit_status disagrees with handoff latest_audit_status")
    if current_audit_status != queue_audit_status:
        errors.append("current latest_audit_status disagrees with compile_queue latest_audit_status")
    if current_audit_ref:
        audit_path, audit_path_error = exact_path(str(current_audit_ref))
        if audit_path_error or audit_path is None or not audit_path.is_file():
            errors.append(f"latest_audit_ref does not resolve exactly: {current_audit_ref}")

    gui_re = re.compile(r"\b(gui|ui|screen|page|panel|form|layout|styling|icon|svg|image|screenshot|visual|button|modal)\b", re.I)
    atom_by_id = {str(atom.get("atom_id")): atom for atom in atoms}
    for atom in atoms:
        atom_id = atom.get("atom_id")
        if atom.get("status") in {"accepted", "ready_for_plan_compile", "compiled_to_plan"} and not atom.get("source_refs"):
            errors.append(f"atom missing source_refs: {atom_id}")
        if "gui_related" not in atom:
            errors.append(f"atom missing gui_related: {atom_id}")
        elif not isinstance(atom.get("gui_related"), bool):
            errors.append(f"atom gui_related must be boolean: {atom_id}")
        haystack = " ".join(str(atom.get(key, "")) for key in ("title", "canonical_summary"))
        haystack += " " + " ".join(map(str, atom.get("exact_tokens", [])))
        reason = str(atom.get("gui_classification_reason", "")).lower()
        explicitly_non_gui_rule = (
            "not gui" in reason
            or "not itself gui" in reason
            or "not gui/ui" in reason
            or "backend/orchestration" in reason
            or "metadata/classification" in reason
        )
        if gui_re.search(haystack) and atom.get("gui_related") is False and not explicitly_non_gui_rule:
            warnings.append(f"review gui_related=false on GUI-looking atom: {atom_id}")
        if atom.get("atom_type") == "negative_constraint" and not atom.get("negative_constraints"):
            warnings.append(f"negative_constraint atom lacks negative_constraints list: {atom_id}")
        if current.get("governance_status") == "sealed":
            for field in ("compile_disposition", "compile_notes", "validation_notes"):
                if contains_stale_governance_pending(atom.get(field, "")):
                    errors.append(f"sealed ledger atom {atom_id} has stale governance-pending {field}")

    queue_source_ids: set[str] = set()
    queue_plan_unit_ids: set[str] = set()
    queue_targets: set[str] = set()
    for item in compile_queue.get("items", []):
        queue_id = item.get("queue_id")
        target_doc = item.get("target_doc")
        if target_doc:
            queue_targets.add(str(target_doc))
            target_path, path_error = exact_path(str(target_doc))
            if path_error or target_path is None or not target_path.exists():
                errors.append(f"compile_queue {queue_id} target_doc does not resolve exactly: {target_doc}")
        for target_doc in item.get("target_docs", []):
            target_path, path_error = exact_path(str(target_doc))
            if path_error or target_path is None or not target_path.exists():
                errors.append(f"compile_queue {queue_id} target_docs entry does not resolve exactly: {target_doc}")
        if not item.get("compiled_plan_unit_ids"):
            errors.append(f"compile_queue {queue_id} missing compiled_plan_unit_ids")
        queue_plan_unit_ids.update(map(str, item.get("compiled_plan_unit_ids", [])))
        for atom_id in item.get("source_atom_ids", []):
            atom_id = str(atom_id)
            queue_source_ids.add(atom_id)
            atom = atom_by_id.get(atom_id)
            if not atom:
                errors.append(f"compile_queue {queue_id} references missing source atom {atom_id}")
                continue
            if item.get("status") == "compiled" and atom.get("status") not in {"compiled_to_plan", "deferred"}:
                errors.append(f"compile_queue {queue_id} source atom {atom_id} status is {atom.get('status')!r}")

    canonical_targets = set(map(str, current.get("canonical_plan_targets", [])))
    if queue_targets

def sync_plan_sharding_evidence(evidence_path: Path, report_path: Path) -> dict[str, Any]:
    require_live_current_evidence(evidence_path)
    data = load_json(evidence_path)
    report = load_json(report_path)
    existing_by_path = {
        artifact.get("path"): artifact
        for artifact in data.get("artifacts", [])
        if artifact.get("path")
    }

    def artifact_for(path: str, *, note: str | None = None) -> dict[str, Any]:
        target = repo_path(path)
        artifact = {k: v for k, v in existing_by_path.get(path, {}).items() if k not in {"sha256", "path"}}
        artifact["path"] = path
        if note is not None:
            artifact["note"] = note
        if target.exists() and target.is_file():
            artifact["sha256"] = sha256_file(target)
        return artifact

    artifacts: list[dict[str, Any]] = [
        artifact_for(str(report.get("config_path", "Plans/sharding_config.json"))),
        artifact_for(str(report_path.relative_to(ROOT))),
    ]
    check_report_path = report_path.with_name("shard-check-report.json")
    if not check_report_path.exists() or not check_report_path.is_file():
        raise SystemExit(
            "live-current plan-sharding evidence requires the adjacent shard-check-report.json: "
            f"{check_report_path.relative_to(ROOT)}"
        )
    artifacts.append(artifact_for(str(check_report_path.relative_to(ROOT))))
    for doc in report.get("docs", []):
        source_path = doc.get("source", {}).get("path")
        if source_path:
            artifacts.append(artifact_for(str(source_path), note="Configured shard source."))
        index_path = doc.get("index_path")
        if index_path:
            artifacts.append(artifact_for(str(index_path)))
        manifest_path = doc.get("manifest_path")
        if manifest_path:
            artifacts.append(artifact_for(str(manifest_path)))
        for shard in doc.get("shards", []):
            shard_path = shard.get("path")
            if shard_path:
                artifacts.append(artifact_for(str(shard_path)))

    old_paths = [artifact.get("path") for artifact in data.get("artifacts", [])]
    new_paths = [artifact.get("path") for artifact in artifacts]
    changed = old_paths != new_paths or data.get("artifacts") != artifacts
    if changed:
        data["artifacts"] = artifacts
        write_json(evidence_path, data)
    return {
        "path": str(evidence_path.relative_to(ROOT)),
        "changed": changed,
        "artifact_count": len(artifacts),
        "removed_paths": sorted(set(old_paths) - set(new_paths)),
        "added_paths": sorted(set(new_paths) - set(old_paths)),
    }

def cmd_refresh(args: argparse.Namespace) -> int:
    schema_version_requests = parse_schema_version_assignments(args.schema_version)
    if schema_version_requests and not args.spec_lock:
        raise SystemExit("--schema-version requires --spec-lock")
    register_files: list[str] = []
    for raw_path in args.register_file:
        candidate = Path(raw_path)
        normalized = candidate.as_posix()
        if (
            candidate.is_absolute()
            or normalized in {"", "."}
            or ".." in candidate.parts
            or normalized != raw_path
        ):
            raise SystemExit(
                "--register-file requires a normalized repository-relative path: "
                f"{raw_path!r}"
            )
        try:
            repo_path(candidate).resolve().relative_to(ROOT.resolve())
        except (OSError, ValueError):
            raise SystemExit(
                "--register-file path must resolve inside the repository: "
                f"{raw_path!r}"
            ) from None
        if normalized in register_files:
            raise SystemExit(f"--register-file was assigned more than once: {normalized}")
        register_files.append(normalized)
    if register_files and not args.spec_lock:
        raise SystemExit("--register-file requires --spec-lock")
    report: dict[str, Any] = {"spec_lock": None, "evidence": []}
    if args.spec_lock:
        report["spec_lock"] = refresh_spec_lock(
            repo_path(args.spec_lock),
            schema_version_requests,
            register_files,
        )
    for evidence_path in args.evidence:
        report["evidence"].append(refresh_evidence(repo_path(evidence_path), args))
    print(json.dumps(report, indent=2, ensure_ascii=False, sort_keys=True))
    return 0

